{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 6,
      "text_ar": "فقال لي: «في البداءة، عندما صُنعت الأرض، قبل أن تُثبت أبواب العالم وققبل أن تهب مجاميع الرياح،",
      "verse": 1
    },
    {
      "chapter": 6,
      "text_ar": "قبل أن تدوّي أصوات الرعد وقبل أن تلمع ومضات البرق، قبل أن تُرسي أسس الفردوس،",
      "verse": 2
    },
    {
      "chapter": 6,
      "text_ar": "قبل أن يُرى الزهر الجميل، قبل أن تثبت قوات الزلزال، قبل أن يجتمع جيش الملائكة لا يُحصى عدده،",
      "verse": 3
    },
    {
      "chapter": 6,
      "text_ar": "قبل أن تترتفع أعالي الهواء، قبل أن تُسمى مقاييس الجلد، قبل أن يُثبت موطئ قدم صهيون،",
      "verse": 4
    },
    {
      "chapter": 6,
      "text_ar": "قبل أن تُحسب السنوات الحالية، وقبل أن تُقصى تخيلات الذين يخطئون الآن، وققبل أن يُختم الذين جمعوا الإيمان ككنز -",
      "verse": 5
    }
  ]
}
